function normalizeAdminMember(member){return {...member,roles:Array.isArray(member.roles)?member.roles:member.role?[member.role]:[],interests:Array.isArray(member.interests)?member.interests.join(', '):(member.interests||''),registered:member.created_at?new Date(member.created_at).toLocaleDateString('ro-RO'):member.registered||'',active:member.active||'—',status:member.status==='active'||member.status==='approved'||member.status==='Activ'?'Activ':member.status==='pending'||member.status==='În așteptare'?'În așteptare':member.status==='rejected'||member.status==='Dezaprobat'?'Dezaprobat':'În așteptare'};}
async function hydrateAdminMembers(){if(adminHydrationStarted)return;adminHydrationStarted=true;try{const result=await listMembers({page:1,pageSize:25});if(result.source!=='supabase'||!result.count){adminTotal=ADMIN_MEMBERS.length;return;}adminHasServerPage=true;adminPage=1;adminTotal=result.count;ADMIN_MEMBERS.splice(0,ADMIN_MEMBERS.length,...result.data.map(normalizeAdminMember));render();}catch(error){adminHydrationStarted=false;console.warn('Admin members sync unavailable',error);}}
