async function hydratePublicContent(){if(publicContentHydrationStarted)return;publicContentHydrationStarted=true;try{const [posts,projects,spaces,events]=await Promise.all([listPosts({pageSize:100}),listProjects({pageSize:100}),listSpaces({pageSize:100}),listEvents({pageSize:100})]);if(posts.source==='supabase'&&posts.count>0){FEED_POSTS.splice(0,FEED_POSTS.length,...posts.data.map((post,index)=>({id:post.id||`demo-feed-${index}`,author:post.author_name||'Membru Viziunea',initial:(post.author_name||'M')[0],role:'Membru',time:new Date(post.created_at).toLocaleDateString('ro-RO'),city:post.city||'Online',distance:0,interest:post.interest||'Comunitate',interests:post.interests||[post.interest||'Comunitate'],image_url:post.image_url||null,title:post.title,body:post.body,action:'Vezi postarea'})));}const replaceResults=(key,result,metaFallback)=>{if(result.source==='supabase'&&result.count>0)DEMO_RESULTS[key]=result.data.map(item=>({title:item.title,meta:item.city||metaFallback,desc:item.description||item.body||''}));};replaceResults('proiecte',projects,'Proiect în comunitate');replaceResults('spatii',spaces,'Spațiu în comunitate');replaceResults('evenimente',events,'Eveniment în comunitate');await hydrateFeedSocialState();if(path()==='/feed'||path()==='/exploreaza')render();}catch(error){publicContentHydrationStarted=false;if(error?.code!=='PGRST205')console.warn('Public content sync unavailable; keeping demo fallback',error);}}
function postPersistenceId(post,index){return post?.id||`demo-feed-${index}`;}
function isRealUser(user=currentUser){return Boolean(user?.id&&!String(user.id).startsWith('demo:'));}
async function hydrateFeedSocialState(){const key=`${currentUser?.id||'demo'}:${FEED_POSTS.map(post=>post.id||post.title).join('|')}`;if(socialHydrationKey===key)return;socialHydrationKey=key;try{const saved=await listSavedPostIds(currentUser);serverSavedPostIds=new Set(saved);const commentEntries=await Promise.all(FEED_POSTS.map(async(post,index)=>[postPersistenceId(post,index),await listPostComments(postPersistenceId(post,index),currentUser)]));serverCommentsByPost=new Map(commentEntries.filter(([,comments])=>comments.length));if(isRealUser()&&saved.length){const records=getSavedFeedRecords();const now=new Date().toISOString();const indexes=saved.map(id=>FEED_POSTS.findIndex((post,index)=>postPersistenceId(post,index)===id)).filter(index=>index>=0);localStorage.setItem(FEED_SAVED_KEY,JSON.stringify([...new Set([...records.map(record=>record.index),...indexes])].map(index=>({index,savedAt:getSavedFeedRecords().find(record=>record.index===index)?.savedAt||now}))));}}catch(error){socialHydrationKey='';console.warn('Social data sync unavailable; keeping demo fallback',error);}}
