function enhanceFeedCityFilter(){if(path()!=='/feed'||feedMode==='create')return;const locationCard=app.querySelector('.feed-location>div');if(!locationCard)return;let select=locationCard.querySelector('[data-feed-city]');const cities=[...new Set(FEED_POSTS.map(post=>post.city).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ro'));if(!select){const current=demoFeed.city;locationCard.querySelector('strong')?.remove();locationCard.querySelector('small')?.remove();locationCard.insertAdjacentHTML('afterbegin',`<label for="feed-city">Oraș<select id="feed-city" name="city" data-feed-city><option value="">Toate orașele</option>${cities.map(city=>`<option value="${city}" ${city===current?'selected':''}>${city}</option>`).join('')}</select></label>`);select=locationCard.querySelector('[data-feed-city]');}if(select)select.value=demoFeed.city||'';const allVisiblePosts=FEED_POSTS.filter(post=>(!demoFeed.interests.length||demoFeed.interests.includes(post.interest))&&(post.distance===0||post.distance<=Number(demoFeed.radius)));const visiblePosts=allVisiblePosts.filter(post=>!demoFeed.city||post.city===demoFeed.city);app.querySelectorAll('.feed-post').forEach((post,index)=>{post.hidden=!allVisiblePosts[index]||Boolean(demoFeed.city&&allVisiblePosts[index].city!==demoFeed.city);});const heading=app.querySelector('.community-feed h2');if(heading)heading.textContent=`${visiblePosts.length} ${visiblePosts.length===1?'postare relevantă':'postări relevante'}`;}
function syncCreateContactField(){const form=app.querySelector('#create-post-form');const method=form?.querySelector('[name="contact_method"]');const field=form?.querySelector('[name="contact_value"]')?.closest('label');const type=form?.querySelector('[name="entity_type"]');const dateField=form?.querySelector('[name="event_date"]')?.closest('label');const notice=form?.querySelector('.create-post-notice');if(notice)notice.textContent=feedNotice;if(method&&field){field.hidden=method.value==='platform';if(method.value==='platform')field.querySelector('input').value='';}if(type&&dateField){dateField.hidden=type.value!=='event';if(type.value!=='event')dateField.querySelector('input').value='';}}
