app.addEventListener('change',event=>{if(path()!=='/exploreaza'||!event.target.matches('.explore-filter'))return;syncExploreDistanceFilter();void refreshExploreFromServer();const filters={};app.querySelectorAll('.explore-filter').forEach(select=>filters[select.dataset.filter]=select.value);let visible=0;app.querySelectorAll('[data-result]').forEach(card=>{const show=Object.entries(filters).every(([key,value])=>!value||(key==='distance'?exploreDistance(card.dataset.location,filters.location)<=Number(value):card.dataset[key]===value));card.hidden=!show;if(show)visible++;});const count=app.querySelector('[data-explore-count]');if(count)count.textContent=`${visible} rezultate`;const empty=app.querySelector('.empty-explore');if(empty)empty.hidden=visible>0;});app.addEventListener('click',event=>{if(path()!=='/exploreaza'||!event.target.closest('[data-explore-reset]'))return;const locationSelect=app.querySelector('[data-filter="location"]');const distanceSelect=app.querySelector('[data-filter="distance"]');if(locationSelect)locationSelect.value='';if(distanceSelect)distanceSelect.value='';syncExploreDistanceFilter();app.querySelectorAll('[data-result]').forEach(card=>card.hidden=false);const count=app.querySelector('[data-explore-count]');if(count)count.textContent=`${app.querySelectorAll('[data-result]').length} rezultate`;const empty=app.querySelector('.empty-explore');if(empty)empty.hidden=true;void refreshExploreFromServer();});
