function showFeedSubmissionSuccess(){const panel=app.querySelector('#create-post-panel');if(!panel)return;panel.innerHTML='<div class="feed-submit-success"><div class="feed-success-emoji" aria-hidden="true">🎉</div><span class="page-kicker">Trimis spre moderare</span><h2>Postarea ta a fost trimisă!</h2><p>Un moderator Viziunea o va verifica înainte să apară în Noutăți. Îți mulțumim că aduci ceva valoros în comunitate.</p><div class="feed-success-actions"><button type="button" class="account-cta" data-feed-success="new">Fă o altă postare <span>→</span></button><button type="button" class="feed-success-secondary" data-feed-success="back">Mergi înapoi la Feed</button></div></div>';}
app.addEventListener('submit',async event=>{if(path()!=='/feed'||!event.target.matches('#create-post-form'))return;event.preventDefault();const formData=new FormData(event.target);const data=Object.fromEntries(formData);data.interests=formData.getAll('interests');if(!data.interests.length){feedNotice='Selectează cel puțin un interes.';enhanceFeedView();syncCreateContactField();return;}try{const imageFile=formData.get('image_file');if(imageFile instanceof File&&imageFile.size)data.image_url=await uploadPostImage(imageFile,currentUser);await createPost(data,currentUser);feedNotice='Postarea a fost trimisă spre moderare.';feedSubmitted=true;event.target.reset();}catch(error){feedNotice=error.message||'Postarea nu a putut fi trimisă.';}enhanceFeedView();syncCreateContactField();if(feedSubmitted)showFeedSubmissionSuccess();});
