app.addEventListener('change',event=>{if(path()!=='/feed'||!event.target.matches('#create-post-image'))return;const file=event.target.files?.[0];const preview=app.querySelector('[data-create-image-preview]');if(!preview)return;if(!file){preview.hidden=true;preview.removeAttribute('src');return;}if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){event.target.value='';preview.hidden=true;preview.removeAttribute('src');feedNotice='Alege o imagine JPG, PNG sau WebP de maximum 10 MB.';enhanceFeedView();return;}preview.src=URL.createObjectURL(file);preview.hidden=false;});
