app.addEventListener('input',event=>{if(path()!=='/mesaje'||!event.target.matches('[data-message-search]'))return;const query=event.target.value.trim().toLowerCase();let visible=0;app.querySelectorAll('[data-message-members] [data-message-member]').forEach(card=>{const show=!query||card.dataset.name.includes(query);card.hidden=!show;if(show)visible++;});const count=app.querySelector('[data-message-result-count]');if(count)count.textContent=visible;const empty=app.querySelector('[data-message-empty]');if(empty)empty.hidden=visible>0;});
