const FEED_SAVED_KEY='viziunea.feed.saved.v1';
const FEED_SEEN_KEY='viziunea.feed.seen.v1';
function feedViewerKey(){return String(currentUser?.email||currentUser?.id||'guest').toLowerCase();}
function getSeenFeedRecords(){try{const rows=JSON.parse(localStorage.getItem(FEED_SEEN_KEY)||'[]');return Array.isArray(rows)?rows.filter(row=>row&&row.user===feedViewerKey()&&Number.isInteger(row.index)):[];}catch{return [];}}
function markFeedSeen(index){const rows=[];try{const stored=JSON.parse(localStorage.getItem(FEED_SEEN_KEY)||'[]');if(Array.isArray(stored))rows.push(...stored);}catch{}const user=feedViewerKey();const next=rows.filter(row=>!(row.user===user&&row.index===index));next.push({user,index,seenAt:new Date().toISOString()});localStorage.setItem(FEED_SEEN_KEY,JSON.stringify(next));}
function resetFeedSeen(){let rows=[];try{const stored=JSON.parse(localStorage.getItem(FEED_SEEN_KEY)||'[]');if(Array.isArray(stored))rows=stored;}catch{}localStorage.setItem(FEED_SEEN_KEY,JSON.stringify(rows.filter(row=>row?.user!==feedViewerKey())));}
function feedPublishedAt(post){if(post?.created_at&&!Number.isNaN(new Date(post.created_at).getTime()))return new Date(post.created_at).getTime();return Date.now();}
function feedPostIsInRange(post){if(!demoFeed.city||!post.city)return true;const distance=exploreDistance(post.city,demoFeed.city);return distance<=Number(demoFeed.radius||100);}
function currentFeedNews(){const seen=new Set(getSeenFeedRecords().map(row=>row.index));const weekAgo=Date.now()-7*24*60*60*1000;return FEED_POSTS.map((post,index)=>({post,index})).filter(({post,index})=>(!demoFeed.interests.length||feedPostInterests(post).some(interest=>demoFeed.interests.includes(interest)))&&feedPostIsInRange(post)&&feedPublishedAt(post)>=weekAgo&&!seen.has(index));}
function enhanceFeedCarousel(){if(path()!=='/feed'||feedMode==='create')return;const posts=app.querySelector('.feed-posts');if(!posts||posts.dataset.carouselReady)return;posts.dataset.carouselReady='true';let active=0;let transitioning=false;let controls;const renderCarousel=()=>{const news=currentFeedNews();active=Math.min(active,Math.max(0,news.length-1));const header=app.querySelector('.community-feed header');if(header){const heading=header.querySelector('h2');if(heading)heading.textContent=news.length?`${news.length} ${news.length===1?'noutate':'noutăți'} disponibile`:'Ai văzut toate noutățile';const meta=header.querySelector('small');if(meta)meta.textContent=news.length?'Swipe dreapta pentru următoarea noutate':'Mărește distanța pentru mai multe noutăți sau alege alt oraș.';}posts.querySelectorAll('.feed-post').forEach(card=>{const index=Number(card.dataset.feedIndex);const position=news.findIndex(item=>item.index===index);card.hidden=position!==active;card.classList.toggle('feed-carousel-active',position===active);});let empty=posts.querySelector('.feed-carousel-empty');if(!news.length){if(!empty){empty=document.createElement('div');empty.className='feed-carousel-empty';posts.append(empty);}empty.innerHTML='<span class="feed-carousel-icon">✓</span><strong>Ai văzut toate noutățile din aria ta.</strong><p>Mărește distanța pentru mai multe noutăți sau alege alt oraș.</p><button type="button" class="feed-demo-refresh" data-feed-reset-seen>Reafișează noutățile demo</button>';}else empty?.remove();controls=app.querySelector('.feed-carousel-controls');if(!controls){controls=document.createElement('div');controls.className='feed-carousel-controls';posts.after(controls);controls.addEventListener('click',event=>{if(event.target.closest('[data-feed-next]'))next();});}controls.innerHTML=news.length?`<span>${active+1} / ${news.length}</span><button type="button" data-feed-next>Următoarea <span>→</span></button>`:'';};const next=()=>{if(transitioning)return;const news=currentFeedNews();if(!news.length)return;const currentIndex=news[active].index;const currentCard=[...posts.querySelectorAll('.feed-post')].find(card=>Number(card.dataset.feedIndex)===currentIndex);transitioning=true;currentCard?.classList.add('feed-card-exit-left');setTimeout(()=>{markFeedSeen(currentIndex);active=Math.min(active,Math.max(0,news.length-2));renderCarousel();const incoming=[...posts.querySelectorAll('.feed-post')].find(card=>!card.hidden);incoming?.classList.add('feed-card-enter-left');requestAnimationFrame(()=>incoming?.classList.remove('feed-card-enter-left'));setTimeout(()=>{transitioning=false;},280);},220);};let startX=0;posts.addEventListener('touchstart',event=>{startX=event.changedTouches[0].clientX;},{passive:true});posts.addEventListener('touchend',event=>{if(event.changedTouches[0].clientX-startX>70)next();},{passive:true});renderCarousel();}
function getSavedFeedRecords(){try{const saved=JSON.parse(localStorage.getItem(FEED_SAVED_KEY)||'[]');return Array.isArray(saved)?saved.map(item=>typeof item==='number'?{index:item,savedAt:new Date().toISOString()}:item).filter(item=>Number.isInteger(item.index)):[];}catch{return [];}}
function getSavedFeedIndexes(){return getSavedFeedRecords().map(item=>item.index);}
function isSavedFeedIndex(index){return getSavedFeedIndexes().includes(index)||serverSavedPostIds.has(postPersistenceId(FEED_POSTS[index],index));}
function setSavedFeedIndexes(indexes){const previous=getSavedFeedRecords();const now=new Date().toISOString();localStorage.setItem(FEED_SAVED_KEY,JSON.stringify([...new Set(indexes)].map(index=>({index,savedAt:previous.find(item=>item.index===index)?.savedAt||now}))));syncSavedNavCount();}
function syncSavedNavCount(){const count=getSavedFeedIndexes().length;document.querySelectorAll('.saved-nav-badge').forEach(badge=>{badge.textContent=count>9?'9+':count;badge.classList.toggle('is-empty',count===0);});}
function enhanceFeedSaved(){if(path()!=='/feed'||feedMode==='create')return;const page=app.querySelector('.feed-page');const posts=page?.querySelectorAll('.feed-post');if(!page||!posts?.length)return;posts.forEach((post,index)=>{post.dataset.feedIndex=index;const save=post.querySelector('[aria-label="Salvează"]');const share=post.querySelector('[aria-label="Distribuie"]');if(save){save.dataset.feedAction='save';save.textContent=isSavedFeedIndex(index)?'♥':'♡';save.classList.toggle('is-saved',isSavedFeedIndex(index));}if(share)share.dataset.feedAction='share';});let saved=page.querySelector('.saved-feed-section');if(!saved){saved=document.createElement('section');saved.className='saved-feed-section';page.querySelector('.community-feed')?.after(saved);}const indexes=getSavedFeedIndexes().filter(index=>FEED_POSTS[index]);saved.innerHTML=`<header><div><span class="page-kicker">La îndemână</span><h2>Postări salvate</h2></div><strong>${indexes.length} ${indexes.length===1?'postare':'postări'}</strong></header>${indexes.length?`<div class="saved-feed-list">${indexes.map(index=>{const post=FEED_POSTS[index];return `<article class="saved-feed-item" data-saved-post="${index}"><div><strong>${esc(post.title)}</strong><small>${esc(post.author)} · ${esc(post.city)}</small></div><button type="button" data-remove-saved="${index}" aria-label="Elimină din salvate">×</button></article>`;}).join('')}</div>`:'<p class="saved-feed-empty">Postările cărora le dai inimă apar aici ca să le găsești rapid mai târziu.</p>'}`;}
function openFeedShare(post){const dialog=document.createElement('dialog');dialog.className='feed-share-dialog';const members=ADMIN_MEMBERS.filter(member=>member.email!==currentUser?.email);const linkUrl=`${location.origin}${BASE_PATH}/feed`;const preset=`Îți trimit această postare din Viziunea: „${post.title}”\n\n${post.body}\n\nVezi postarea în Feed: ${linkUrl}`;dialog.innerHTML=`<form method="dialog"><button class="detail-close" value="cancel" aria-label="Închide">×</button><span class="page-kicker">Distribuie postarea</span><h2>${esc(post.title)}</h2><p class="feed-share-preview">${esc(post.body)}</p><label>Mesajul tău<textarea name="share_body" rows="6">${esc(preset)}</textarea></label><div class="feed-share-options"><button type="button" data-share-copy>Copiază linkul</button><a href="https://wa.me/?text=${encodeURIComponent(preset)}" target="_blank" rel="noopener">WhatsApp</a><a href="mailto:?subject=${encodeURIComponent(`Postare Viziunea: ${post.title}`)}&body=${encodeURIComponent(preset)}">Email</a></div><div class="feed-share-member"><label>Trimite unui membru Viziunea<select name="recipient"><option value="">Alege un membru...</option>${members.map(member=>`<option value="${esc(member.email)}">${esc(member.name)} · ${esc(member.city)}</option>`).join('')}</select></label><button type="button" class="admin-action" data-share-member>Trimite mesajul <span>→</span></button></div><p class="feed-share-notice"></p></form>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('[data-share-copy]')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(linkUrl);dialog.querySelector('.feed-share-notice').textContent='Link copiat.';}catch{dialog.querySelector('.feed-share-notice').textContent=linkUrl;}});dialog.querySelector('[data-share-member]')?.addEventListener('click',async()=>{const email=dialog.querySelector('[name="recipient"]').value;const member=members.find(item=>item.email===email);if(!member){dialog.querySelector('.feed-share-notice').textContent='Alege un membru.';return;}try{await sendMessage({from:currentUser,to:{id:member.id||`demo:${member.email}`,email:member.email,user_metadata:{full_name:member.name}},body:dialog.querySelector('[name="share_body"]').value});dialog.querySelector('.feed-share-notice').textContent=`Postarea a fost trimisă lui ${member.name}.`;dialog.querySelector('[name="recipient"]').value='';}catch(error){dialog.querySelector('.feed-share-notice').textContent=error.message||'Mesajul nu a putut fi trimis.';}});dialog.addEventListener('close',()=>dialog.remove());}
app.addEventListener('click',event=>{if(path()!=='/feed')return;const remove=event.target.closest?.('[data-remove-saved]');if(remove){const index=Number(remove.dataset.removeSaved);setSavedFeedIndexes(getSavedFeedIndexes().filter(item=>item!==index));serverSavedPostIds.delete(postPersistenceId(FEED_POSTS[index],index));void togglePostSave(currentUser,postPersistenceId(FEED_POSTS[index],index),false).catch(error=>console.warn('Save removal failed',error));enhanceFeedSaved();return;}const action=event.target.closest?.('[data-feed-action]');if(!action)return;const card=action.closest('.feed-post');const index=Number(card?.dataset.feedIndex);const post=FEED_POSTS[index];if(!post)return;if(action.dataset.feedAction==='save'){const saved=isSavedFeedIndex(index);const next=!saved;setSavedFeedIndexes(next?[...getSavedFeedIndexes(),index]:getSavedFeedIndexes().filter(item=>item!==index));if(next)serverSavedPostIds.add(postPersistenceId(post,index));else serverSavedPostIds.delete(postPersistenceId(post,index));void togglePostSave(currentUser,postPersistenceId(post,index),next).catch(error=>console.warn('Save sync failed',error));enhanceFeedSaved();}else if(action.dataset.feedAction==='share')openFeedShare(post);});
function syncFeedIndexes(){if(path()!=='/feed')return;app.querySelectorAll('.feed-post').forEach(post=>{const title=post.querySelector('h3')?.textContent.trim();const index=FEED_POSTS.findIndex(item=>item.title===title);if(index>=0)post.dataset.feedIndex=index;});}
function ensureSavedFeedPanel(){if(path()!=='/feed'||feedMode==='create')return;const page=app.querySelector('.feed-page');if(!page||page.querySelector('.saved-feed-section'))return;const section=document.createElement('section');section.className='saved-feed-section';section.innerHTML='<header><div><span class="page-kicker">La îndemână</span><h2>Postări salvate</h2></div><strong>0 postări</strong></header><p class="saved-feed-empty">Postările cărora le dai inimă apar aici ca să le găsești rapid mai târziu.</p>';page.querySelector('.community-feed')?.after(section);}
function commentMentionMembers(body){const tokens=body.match(/@[\p{L}0-9._-]+/gu)||[];return ADMIN_MEMBERS.filter(member=>tokens.some(token=>{const handle=token.slice(1).toLocaleLowerCase('ro');return member.name.toLocaleLowerCase('ro').split(/\s+/)[0]===handle||member.email.split('@')[0].toLocaleLowerCase()===handle;}));}
function renderCommentTree(comments,parentId=null,depth=0){return comments.filter(comment=>(comment.parentId||comment.parent_id||null)===parentId).map(comment=>`<article class="feed-comment ${depth?'is-reply':''}" data-comment-id="${esc(comment.id)}"><span class="feed-comment-avatar">${esc((comment.authorName||'Membru Viziunea')[0]||'M')}</span><div class="feed-comment-body"><div><strong>${esc(comment.authorName||'Membru Viziunea')}</strong><time>${new Date(comment.created_at).toLocaleString('ro-RO')}</time></div><p>${esc(comment.body).replace(/(@[\p{L}0-9._-]+)/gu,'<b>$1</b>')}</p><button type="button" data-comment-reply="${esc(comment.id)}">Răspunde</button>${renderCommentTree(comments,comment.id,depth+1)}</div></article>`).join('');}
function normalizeServerComment(comment){const member=ADMIN_MEMBERS.find(item=>item.id===comment.author_id);return {...comment,authorName:member?.name||currentUser?.user_metadata?.full_name||'Membru Viziunea',parentId:comment.parent_id||null};}
function enhanceFeedComments(){if(path()!=='/feed'||feedMode==='create')return;app.querySelectorAll('.feed-post').forEach(post=>{const index=Number(post.dataset.feedIndex);if(!Number.isInteger(index)||index<0)return;let section=post.querySelector('.feed-comments');if(!section){section=document.createElement('section');section.className='feed-comments';post.append(section);}const comments=serverCommentsByPost.get(postPersistenceId(FEED_POSTS[index],index))?.map(normalizeServerComment)||listComments(`demo-feed-${index}`);section.innerHTML=`<div class="feed-comments-heading"><strong>${comments.length} ${comments.length===1?'comentariu':'comentarii'}</strong></div>${comments.length?`<div class="feed-comment-list">${renderCommentTree(comments)}</div>`:''}<form class="feed-comment-form" data-comment-form data-post-index="${index}"><textarea name="body" rows="1" required placeholder="Scrie un comentariu..."></textarea><button type="submit">Comentează</button></form>`;});}
app.addEventListener('click',event=>{if(path()!=='/feed')return;const reply=event.target.closest?.('[data-comment-reply]');if(!reply)return;const comment=reply.closest('.feed-post')?.querySelector('[data-comment-form]');if(!comment)return;comment.dataset.parentId=reply.dataset.commentReply;const textarea=comment.querySelector('textarea');textarea.placeholder='Răspunde la acest comentariu...';textarea.focus();});
app.addEventListener('submit',async event=>{if(path()!=='/feed'||!event.target.matches('[data-comment-form]'))return;event.preventDefault();const form=event.target;const body=String(new FormData(form).get('body')||'').trim();const index=Number(form.dataset.postIndex);const post=FEED_POSTS[index];if(!post)return;try{const mentions=commentMentionMembers(body);const parentId=form.dataset.parentId||null;const postId=postPersistenceId(post,index);if(isRealUser()){const comment=await addPostComment({postId,authorId:currentUser.id,body,parentId},currentUser);serverCommentsByPost.set(postId,[...(serverCommentsByPost.get(postId)||[]),comment]);}else{addComment({postKey:`demo-feed-${index}`,author:currentUser,body,parentId,mentions:mentions.map(member=>member.email)});}await Promise.all(mentions.map(member=>notifyMention({from:currentUser,to:{id:member.id||`demo:${member.email}`,email:member.email,user_metadata:{full_name:member.name}},body,postTitle:post.title})));app.querySelectorAll('.feed-comments').forEach(section=>section.remove());enhanceFeedComments();}catch(error){form.insertAdjacentHTML('afterend',`<p class="feed-comment-error">${esc(error.message||'Comentariul nu a putut fi trimis.')}</p>`);}});
function feedPostInterests(post){return Array.isArray(post.interests)&&post.interests.length?post.interests:[post.interest].filter(Boolean);}
function enhanceFeedInterestCounts(){if(path()!=='/feed'||feedMode==='create')return;const counts=FEED_POSTS.reduce((result,post)=>{feedPostInterests(post).forEach(interest=>{result[interest]=(result[interest]||0)+1;});return result;},{});app.querySelectorAll('.feed-choice').forEach(button=>{const label=button.dataset.feedInterest;const text=`${label} (${counts[label]||0})`;if(button.textContent!==text)button.textContent=text;});}
function enhanceFeedCityOptions(){if(path()!=='/feed'||feedMode==='create')return;const select=app.querySelector('[data-feed-city]');if(!select)return;const filtered=FEED_POSTS.filter(post=>!demoFeed.interests.length||demoFeed.interests.some(interest=>feedPostInterests(post).includes(interest)));const counts=filtered.reduce((result,post)=>{if(post.city)result[post.city]=(result[post.city]||0)+1;return result;},{});const html=`<option value="">Toate orașele (${filtered.length})</option>${Object.entries(counts).filter(([,count])=>count>0).sort(([a],[b])=>a.localeCompare(b,'ro')).map(([city,count])=>`<option value="${esc(city)}">${esc(city)} (${count})</option>`).join('')}`;if(select.innerHTML!==html){const current=select.value;select.innerHTML=html;select.value=Object.prototype.hasOwnProperty.call(counts,current)?current:'';}}
function enhanceFeedCityResults(){if(path()!=='/feed'||feedMode==='create')return;const active=FEED_POSTS.filter(post=>(!demoFeed.interests.length||demoFeed.interests.some(interest=>feedPostInterests(post).includes(interest)))&&feedPostIsInRange(post));const visible=active.filter(post=>!demoFeed.city||feedPostIsInRange(post));app.querySelectorAll('.feed-post').forEach(post=>{const index=Number(post.dataset.feedIndex);post.hidden=!visible.some(item=>FEED_POSTS.indexOf(item)===index);});}
function syncMessageDistanceFilter(){if(path()!=='/mesaje')return;const city=app.querySelector('[data-message-filter="city"]');const distance=app.querySelector('[data-message-filter="distance"]');if(!city||!distance)return;const hasCity=Boolean(city.value);distance.disabled=!hasCity;if(!hasCity){distance.value='';return;}if(!distance.value)distance.value='100';}
app.addEventListener('change',event=>{if(path()!=='/mesaje'||!event.target.matches('[data-message-filter]'))return;syncMessageDistanceFilter();applyMessageDirectoryFilters();});
function enhanceMessageInterestFilter(){if(path()!=='/mesaje')return;const select=app.querySelector('select[data-message-filter="interest"]');if(!select)return;const options=[...select.options].slice(1);const fieldset=document.createElement('fieldset');fieldset.className='message-interest-filter';fieldset.innerHTML=`<legend>Interese</legend><div>${options.map(option=>`<label><input type="checkbox" data-message-filter="interest" data-message-interest value="${esc(option.value)}"><span>${esc(option.textContent)}</span></label>`).join('')}</div>`;select.closest('label')?.replaceWith(fieldset);refreshMessageDirectory();}
function refreshMessageDirectory(){if(path()!=='/mesaje')return;const values={city:app.querySelector('[data-message-filter="city"]')?.value||'',distance:app.querySelector('[data-message-filter="distance"]')?.value||'',role:app.querySelector('[data-message-filter="role"]')?.value||''};const interests=[...app.querySelectorAll('[data-message-interest]:checked')].map(input=>input.value);const query=app.querySelector('[data-message-search]')?.value.trim().toLowerCase()||'';const cards=[...app.querySelectorAll('[data-message-members] [data-message-member]')];let visible=0;cards.forEach(card=>{const matches=card.dataset.interests.split(', ').filter(Boolean);const score=interests.filter(interest=>matches.includes(interest)).length;const show=(!query||card.dataset.name.includes(query))&&(!values.city||messageDistance(card.dataset.city,values.city)<=Number(values.distance||9999))&&(!values.distance||messageDistance(card.dataset.city,values.city||demoProfile.city)<=Number(values.distance))&&(!values.role||card.dataset.roles.split('|').includes(values.role))&&(!interests.length||score>0);card.hidden=!show;card.dataset.interestScore=score;card.style.order=show?String(100-score):'999';if(show)visible++;});const count=app.querySelector('[data-message-result-count]');if(count)count.textContent=visible;const empty=app.querySelector('[data-message-empty]');if(empty)empty.hidden=visible>0;const container=app.querySelector('[data-message-members]');if(container)cards.sort((a,b)=>Number(a.dataset.interestScore||0)<Number(b.dataset.interestScore||0)?1:-1).forEach(card=>container.append(card));}
app.addEventListener('input',event=>{if(path()==='/mesaje'&&event.target.matches('[data-message-search]'))refreshMessageDirectory();});
app.addEventListener('change',event=>{if(path()==='/mesaje'&&(event.target.matches('[data-message-filter]')||event.target.matches('[data-message-interest]'))){syncMessageDistanceFilter();refreshMessageDirectory();}});
const FEED_IMAGE_PLACEHOLDER="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 900 600'%3E%3Crect width='900' height='600' fill='%23e9f3e8'/%3E%3Ccircle cx='450' cy='260' r='90' fill='%23cfe9d1'/%3E%3Cpath d='M390 280l40-40 35 28 35-45 60 65' fill='none' stroke='%234c8052' stroke-width='14' stroke-linecap='round' stroke-linejoin='round'/%3E%3Ctext x='450' y='430' text-anchor='middle' font-family='Arial' font-size='34' fill='%23285c47'%3EImagine demo Viziunea%3C/text%3E%3C/svg%3E";
const DEMO_FEED_IMAGES=[FEED_IMAGE_PLACEHOLDER,FEED_IMAGE_PLACEHOLDER,FEED_IMAGE_PLACEHOLDER];
function enhanceFeedImages(){if(path()!=='/feed'||feedMode==='create')return;app.querySelectorAll('.feed-post').forEach(post=>{if(post.querySelector('.feed-post-image'))return;const index=Number(post.dataset.feedIndex);const image=FEED_POSTS[index]?.image_url||DEMO_FEED_IMAGES[index];if(!image)return;post.classList.add('has-image');post.insertAdjacentHTML('afterbegin',`<img class="feed-post-image" src="${esc(image)}" alt="Imagine reprezentativă pentru ${esc(FEED_POSTS[index].title)}" loading="lazy">`);});}
function enhanceCreatePostImageField(){if(path()!=='/feed'||feedMode!=='create')return;const grid=app.querySelector('.create-post-grid');if(!grid||grid.querySelector('[name="image_file"]'))return;grid.insertAdjacentHTML('beforeend','<label class="create-post-wide">Imagine reprezentativă (opțional)<input id="create-post-image" name="image_file" type="file" accept="image/jpeg,image/png,image/webp"><small class="create-image-help">JPG, PNG sau WebP · maximum 10 MB.</small><img class="create-image-preview" data-create-image-preview alt="Previzualizare imagine" hidden></label>');}
